        return "刚刚";
    }
    var arrayObj = [
                [31536000, "年前"],
                [2592000, "个月前"],
                [604800, "星期前"],
                [86400, "天前"],
                [3600, "小时前"],
                [60, "刚刚"],
                [1, "刚刚"]
